import{_ as p,a0 as i,w as r,s as u,I as n,x as e,a1 as l,A as o,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Celeste：Rust 开发的多云端开源 GUI 文件同步客户端 | LCTT x X-CMD","titleTemplate":false,"description":"Celeste：Rust 开发的多云端开源 GUI 文件同步客户端 | LCTT (202312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Celeste：Rust 开发的多云端开源 GUI 文件同步客户端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Celeste：Rust 开发的多云端开源 GUI 文件同步客户端 | LCTT (202312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202312/20231212 Celeste- A Multi-Cloud Open-Source GUI File Sync Client in Rust","title":"Celeste：Rust 开发的多云端开源 GUI 文件同步客户端","tag":"202312","desc":""},"relativePath":"202312/20231212 Celeste- A Multi-Cloud Open-Source GUI File Sync Client in Rust.md","filePath":"[post].md"}'),m={name:"202312/20231212 Celeste- A Multi-Cloud Open-Source GUI File Sync Client in Rust.md"};function d(f,t,C,g,x,b){const s=i("Link");return r(),u("div",null,[t[22]||(t[22]=n("h1",{id:"celeste-rust-开发的多云端开源-gui-文件同步客户端",tabindex:"-1"},[e("Celeste：Rust 开发的多云端开源 GUI 文件同步客户端 "),n("a",{class:"header-anchor",href:"#celeste-rust-开发的多云端开源-gui-文件同步客户端","aria-label":"Permalink to “Celeste：Rust 开发的多云端开源 GUI 文件同步客户端”"},"​")],-1)),t[23]||(t[23]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202312/20/210937s96kbwwycd71ciiu.jpg",alt:""})],-1)),t[24]||(t[24]=n("blockquote",null,[n("p",null,"一个简单而优雅的 GUI 同步客户端，提供双向同步。")],-1)),n("p",null,[t[3]||(t[3]=e("当谈到与云文件同步时，我们有 ",-1)),l(s,{href:"https://itsfoss.com/insync-linux-review/"},{default:o(()=>[...t[0]||(t[0]=[e("Insync",-1)])]),_:1}),t[4]||(t[4]=e("、",-1)),l(s,{href:"https://itsfoss.com/freefilesync/"},{default:o(()=>[...t[1]||(t[1]=[e("FreeFileSync",-1)])]),_:1}),t[5]||(t[5]=e(" 等选项，以及 ",-1)),l(s,{href:"https://itsfoss.com/use-onedrive-linux-rclone/"},{default:o(()=>[...t[2]||(t[2]=[e("rclone",-1)])]),_:1}),t[6]||(t[6]=e(" 等几个命令行工具。",-1))]),t[25]||(t[25]=a('<p>无论哪种情况，你也可以使用云存储提供商的同步客户端（如果他们有适用于 Linux 或任何其他平台的同步客户端）。但是，这并不是与多个云存储服务同步内容的最佳方式。</p><p>Insync 是一款付费工具，而 FreeFileSync 或 rclone 对于 Linux 新用户来说可能是一种难以接受的选择。。</p><p>Celeste，一个简单的 GUI 同步客户端，支持多个云提供商。</p><blockquote><p>📋 该应用正在积极开发中。目前它可能没有足够的功能和贡献者。欢迎你探索并帮助该项目。</p></blockquote><h3 id="适用于-linux-的基于-rust-的同步客户端" tabindex="-1">适用于 Linux 的基于 Rust 的同步客户端 <a class="header-anchor" href="#适用于-linux-的基于-rust-的同步客户端" aria-label="Permalink to “适用于 Linux 的基于 Rust 的同步客户端”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste.png" alt=""></p><p>Celeste 是一款用 Rust 编写的应用，可确保你获得快速的体验。它在底层利用 rclone 来可靠地将数据与云同步。</p><p>与某些现有选项不同，它没有为你提供很多选择。虽然一些用户可能会发现它有所欠缺，但其他用户可能会发现它是他们一直想要的简单工具。</p><p>Celeste 仅支持双向同步，目前没有其他同步方式。</p><p>如果你想要单向同步（云到本地，或本地到云），那么这不适合你。</p><p>该工具的工作机制很简单。你只需从列表中添加云提供商，或添加任何 WebDAV 服务器。</p><p>默认选项包括：<strong>Google Drive、Dropbox、Proton Drive、pCloud、ownCloud、</strong> 和 <strong>Nextcloud</strong>。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste-options.png" alt=""></p><p>你可以自定义该工具的服务器名称，然后点击“<ruby>登录<rt>Log in</rt></ruby>”开始授权过程。pCloud 的情况如下：</p><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste-pcloud.png" alt=""></p><p>当你授权应用访问云文件，它会提示你设置本地文件夹和云之间的同步。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste-sync-location.png" alt=""></p><p>如果还没有正斜杠（<code>/</code>） 符号，那么只需输入它即可，它应该开始以下拉样式列出你拥有的远程文件夹。</p><blockquote><p>💡 这将是双向同步。因此，你的云文件将被下载到远程文件夹（如果有）。同步后，从云中删除的任何内容都不会从本地文件夹中消失。而且，你从系统中删除的任何内容都将从云中删除。</p></blockquote><p><strong>此同步过程定期发生。</strong> 我没有找到强制启动或停止同步的方法。如果此应用的未来版本中提供类似的选项，它应该会有所帮助。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste-gui-sync-check.png" alt=""></p><p>在大多数情况下，每当本地/远程中发生文件更改时，同步都会确保你能够尽快访问最新的更改。</p><p>有一次，很长一段时间没有同步，所以我不得不重新启动应用来修复它。</p><p>不幸的是，如果云提供商的令牌过期，该应用不能很好地处理错误，并且你必须重新授权和重新同步。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste-dropbox-error.png" alt=""></p><p>它会显示错误，但没有使用 GUI 刷新令牌的选项。我不想尝试命令行方式，因为这违背了 GUI 工具的目的。</p><p>因此，你可以选择再次重新添加相同的同步服务器，重新进行所有授权和同步。这就是目前的解决方案。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Celeste 似乎是一个非常有用且简单的 GUI 同步客户端。</p><p>尽管它缺乏某些功能，但用户体验对于它已经提供的功能来说还是很好的。</p><p>考虑到它是一个相当新的应用，有更多的贡献者和用户尝试它，Celeste 可以凭借其坚实的基础发展成更多的东西。</p><p>你觉得 Celeste 怎么样？ 在下面的评论中分享你的想法。</p><p><em>（题图：DA/48cf6b8e-8f5a-46e4-a7c1-50fe1cfd068f）</em></p><hr>',34)),n("p",null,[t[8]||(t[8]=e("via: ",-1)),l(s,{href:"https://news.itsfoss.com/celeste/"},{default:o(()=>[...t[7]||(t[7]=[e("https://news.itsfoss.com/celeste/",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=e("作者：",-1)),l(s,{href:"https://news.itsfoss.com/author/ankush/"},{default:o(()=>[...t[9]||(t[9]=[e("Ankush Das",-1)])]),_:1}),t[14]||(t[14]=e(" 选题：",-1)),l(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[10]||(t[10]=[e("lujun9972",-1)])]),_:1}),t[15]||(t[15]=e(" 译者：",-1)),l(s,{href:"https://github.com/geekpi"},{default:o(()=>[...t[11]||(t[11]=[e("geekpi",-1)])]),_:1}),t[16]||(t[16]=e(" 校对：",-1)),l(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[12]||(t[12]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=e("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[17]||(t[17]=[e("LCTT",-1)])]),_:1}),t[20]||(t[20]=e(" 原创编译，",-1)),l(s,{href:"https://linux.cn/"},{default:o(()=>[...t[18]||(t[18]=[e("Linux中国",-1)])]),_:1}),t[21]||(t[21]=e(" 荣誉推出",-1))])])}const w=p(m,[["render",d]]);export{k as __pageData,w as default};
